#include <iostream>
#include <algorithm>

using namespace std;

bool check(long long m, long long L, long long A) {
    __int128 sum = (__int128)m * A + (__int128)m * (m - 1) / 2;
    return sum < L;
}

void solve() {
    long long L, A, B;
    if (!(cin >> L >> A >> B)) return;

    long long max_m = B - A;
    long long low = 0, high = min(max_m, 50000000LL);
    long long best_m = 0;

    while (low <= high) {
        long long mid = low + (high - low) / 2;
        if (check(mid, L, A)) {
            best_m = mid;
            low = mid + 1;
        } else {
            high = mid - 1;
        }
    }

    cout << best_m + 1 << "\n";
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int P;
    if (cin >> P) {
        while (P--) {
            solve();
        }
    }
    return 0;
}
